import React, { useState, useEffect, useCallback } from 'react';

export default function TreasureCardModal({ 
    isOpen = false, 
    card = null, 
    onClose = () => {} 
}) {
    const [modalState, setModalState] = useState('open');

    useEffect(() => {
        if (isOpen) {
            setModalState('open');
        }
    }, [isOpen]);

    const handleClose = useCallback(() => {
        if (modalState !== 'closing') {
            setModalState('closing');
            onClose();
        }
    }, [modalState, onClose]);

    const handleImageError = useCallback((e) => {
        e.target.src = '/img/placeholder.png';
    }, []);

    if (!isOpen || card == null) {
        return null;
    }

    return (
        <div 
            className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80"
            onClick={handleClose}
            role="dialog"
            aria-modal="true"
        >
            <div 
                className="relative flex items-center justify-center p-4"
                onClick={(e) => e.stopPropagation()}
            >
                <img
                    src={`/img/cartetesoro/${card.immagine}`}
                    alt={card.effetto || 'Treasure Card'}
                    onError={handleImageError}
                    onClick={handleClose}
                    className="max-w-full max-h-[90vh] object-contain cursor-pointer rounded-xl shadow-2xl"
                />
            </div>
        </div>
    );
}